<h1>الأقسام</h1><form method="post" enctype="multipart/form-data" action="<?= url('/admin/categories/save') ?>" class="card card-body mb-4"><?= csrf_field() ?><div class="row g-2"><div class="col-md"><input name="name_ar" class="form-control" placeholder="اسم القسم" required></div><div class="col-md"><input name="slug" class="form-control" placeholder="الرابط"></div><div class="col-md"><input name="sort_order" type="number" class="form-control" value="0"></div><div class="col-md"><input type="file" name="image" class="form-control"></div><div class="col-md-auto"><label><input type="checkbox" name="is_active" checked> نشط</label></div><div class="col-md-auto"><button class="btn btn-success">إضافة</button></div></div></form><table class="table bg-white"><tr><th>الصورة</th><th>الاسم</th><th>الرابط</th><th>الترتيب</th><th></th></tr><?php foreach($categories as $c): ?><tr><form method="post" enctype="multipart/form-data" action="<?= url('/admin/categories/save') ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $c['id'] ?>"><td><img src="<?= e($c['image_url'] ? url($c['image_url']) : 'https://placehold.co/80x80?text=Cat') ?>" width="50"><input type="file" name="image" class="form-control form-control-sm"></td><td><input name="name_ar" class="form-control" value="<?= e($c['name_ar']) ?>"></td><td><input name="slug" class="form-control" value="<?= e($c['slug']) ?>"></td><td><input name="sort_order" type="number" class="form-control" value="<?= $c['sort_order'] ?>"><label><input type="checkbox" name="is_active" <?= $c['is_active']?'checked':'' ?>> نشط</label></td><td><button class="btn btn-sm btn-primary">حفظ</button></form><form method="post" action="<?= url('/admin/categories/delete') ?>" class="d-inline"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $c['id'] ?>"><button class="btn btn-sm btn-danger">حذف</button></form></td></tr><?php endforeach; ?></table>
